run.command:
$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$secs = 15
$ads = @(Get-NetAdapter | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notmatch 'Loopback' })
if (-not $ads.Count) { 'THROUGHPUT-ERROR: no network adapter is up.'; exit 1 }
$physical = @{}; $speed = @{}; foreach ($a in $ads) { $physical[$a.Name] = -not $a.Virtual; $speed[$a.Name] = [string]$a.LinkSpeed }
function Stats { $h = @{}; foreach ($s in (Get-NetAdapterStatistics)) { $h[$s.Name] = @([double]$s.ReceivedBytes, [double]$s.SentBytes) }; return $h }
function Mbps($bytes, $sec) { return [math]::Round($bytes * 8 / 1000000 / [math]::Max($sec, 0.001), 2) }
function Fmt-Bytes($b) { if ($b -ge 1GB) { return ('{0:n2} GB' -f ($b / 1GB)) }; if ($b -ge 1MB) { return ('{0:n1} MB' -f ($b / 1MB)) }; if ($b -ge 1KB) { return ('{0:n0} KB' -f ($b / 1KB)) }; return ([int]$b).ToString() + ' B' }
$bars = [char[]]@(0x2581, 0x2582, 0x2583, 0x2584, 0x2585, 0x2586, 0x2587, 0x2588); $scale = @(0.1, 0.5, 2, 5, 20, 50, 200)
function Bar($m) { $i = 0; foreach ($t in $scale) { if ($m -gt $t) { $i++ } }; return $bars[$i] }
$hist = @{}; foreach ($a in $ads) { $hist[$a.Name] = @{ In = New-Object Collections.Generic.List[double]; Out = New-Object Collections.Generic.List[double]; Spark = '' } }
'Watching ' + (($ads | ForEach-Object { $_.Name }) -join ', ') + ' for ' + $secs + ' s: bytes in and out per second from the adapter counters. Nothing is captured; use the network normally.'
''
$prev = Stats; $sw = [Diagnostics.Stopwatch]::StartNew(); $lastT = 0.0
for ($i = 1; $i -le $secs; $i++) {
  Start-Sleep -Seconds 1
  $cur = Stats; $t = $sw.Elapsed.TotalSeconds; $dt = $t - $lastT; $lastT = $t
  $parts = foreach ($a in $ads) {
    $n = $a.Name; if (-not $cur.ContainsKey($n) -or -not $prev.ContainsKey($n)) { continue }
    $din = [math]::Max($cur[$n][0] - $prev[$n][0], 0); $dout = [math]::Max($cur[$n][1] - $prev[$n][1], 0)
    $mi = Mbps $din $dt; $mo = Mbps $dout $dt
    $hist[$n].In.Add($mi); $hist[$n].Out.Add($mo); $hist[$n].Spark += (Bar ($mi + $mo))
    if ($physical[$n] -or ($din + $dout) -gt 2048) { ('{0,-1} in {1,7} out {2,7} Mbit/s {3,-1}' -f $n, $mi, $mo, (Bar ($mi + $mo))) }
  }
  $prev = $cur
  ('{0,3} s  ' -f $i) + (& { if ($parts) { $parts -join '   |   ' } else { '(quiet)' } })
}
''
'Summary over ' + $secs + ' s'
$rows = foreach ($a in $ads) {
  $h = $hist[$a.Name]; if (-not $h.In.Count) { continue }
  $avgIn = ($h.In | Measure-Object -Average).Average; $avgOut = ($h.Out | Measure-Object -Average).Average
  $totIn = ($h.In | Measure-Object -Sum).Sum * 1000000 / 8; $totOut = ($h.Out | Measure-Object -Sum).Sum * 1000000 / 8
  if (-not $physical[$a.Name] -and ($totIn + $totOut) -lt 10240) { continue }
  [pscustomobject]@{ Adapter = $a.Name; Link = $speed[$a.Name]; 'Avg in' = ('{0:n2}' -f $avgIn); 'Avg out' = ('{0:n2}' -f $avgOut); 'Peak in' = ('{0:n2}' -f ($h.In | Measure-Object -Maximum).Maximum); 'Peak out' = ('{0:n2}' -f ($h.Out | Measure-Object -Maximum).Maximum); Received = (Fmt-Bytes $totIn); Sent = (Fmt-Bytes $totOut); Activity = $h.Spark }
}
if ($rows) { ($rows | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd(); 'Rates are Mbit/s; Activity is one bar per second of in+out (' + ($scale -join '/') + ' Mbit/s steps).' } else { '  no traffic on any adapter' }
''
$busy = $null; $busyRate = 0
foreach ($a in $ads) { $h = $hist[$a.Name]; if (-not $h.In.Count) { continue }; $r = ($h.In | Measure-Object -Average).Average + ($h.Out | Measure-Object -Average).Average; if ($r -gt $busyRate) { $busyRate = $r; $busy = $a } }
if (-not $busy -or $busyRate -lt 0.2) { 'Idle: under 0.2 Mbit/s on every adapter for the whole run. Nothing on this PC is using the connection right now; if the internet still feels slow, the cause is outside this PC (try "Why is everything slow?").' }
else {
  $h = $hist[$busy.Name]; $pi = ($h.In | Measure-Object -Maximum).Maximum; $po = ($h.Out | Measure-Object -Maximum).Maximum
  $link = 0; if ($speed[$busy.Name] -match '([\d.]+) (Gbps|Mbps)') { $link = [double]$Matches[1] * (& { if ($Matches[2] -eq 'Gbps') { 1000 } else { 1 } }) }
  $pct = ''; if ($link -gt 0) { $pct = ' - ' + [math]::Round(100 * [math]::Max($pi, $po) / $link) + '% of the ' + $speed[$busy.Name] + ' link at the peak' }
  'Busy: ' + $busy.Name + ' averaged ' + ('{0:n1}' -f (($h.In | Measure-Object -Average).Average)) + ' Mbit/s in and ' + ('{0:n1}' -f (($h.Out | Measure-Object -Average).Average)) + ' Mbit/s out, peaking at ' + ('{0:n1}' -f $pi) + ' in / ' + ('{0:n1}' -f $po) + ' out' + $pct + '. That is real traffic from this PC. "Per-process network activity" names the program; a steady upload with nothing running is worth a look (backups, cloud sync, or something you did not install).'
