  $link = 0; if ($speed[$busy.Name] -match '([\d.]+) (Gbps|Mbps)') { $link = [double]$Matches[1] * (& { if ($Matches[2] -eq 'Gbps') { 1000 } else { 1 } }) }
  $pct = ''; if ($link -gt 0) { $pct = ' - ' + [math]::Round(100 * [math]::Max($pi, $po) / $link) + '% of the ' + $speed[$busy.Name] + ' link at the peak' }
