run.command:
$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$vpnRx = 'VPN|WireGuard|Tailscale|NetBird|OpenVPN|TAP-Windows|Wintun|ZeroTier|Cisco AnyConnect|Fortinet|GlobalProtect|Mullvad|NordLynx|Proton|ExpressVPN|Surfshark|WAN Miniport \((PPTP|L2TP|SSTP|IKEv2)\)'
$adapters = @(Get-NetAdapter | Where-Object { $_.Status -eq 'Up' })
$vpn = @($adapters | Where-Object { $_.InterfaceDescription -match $vpnRx -or $_.Name -match 'VPN|^wt\d|tailscale|^zt|Mullvad|Proton|Nord' })
$vpnIdx = @($vpn | ForEach-Object { [int]$_.ifIndex })
$mtu = @{}; foreach ($i in @(Get-NetIPInterface -AddressFamily IPv4)) { $mtu[[int]$i.ifIndex] = [int]$i.NlMtu }
$ipOf = @{}; foreach ($a in @(Get-NetIPAddress -AddressFamily IPv4 | Where-Object { $_.IPAddress -notlike '169.254.*' })) { if (-not $ipOf.ContainsKey([int]$a.InterfaceIndex)) { $ipOf[[int]$a.InterfaceIndex] = [string]$a.IPAddress } }
$dnsOf = @{}; foreach ($d in @(Get-DnsClientServerAddress -AddressFamily IPv4)) { $dnsOf[[int]$d.InterfaceIndex] = ($d.ServerAddresses -join ', ') }
'1. VPN adapters that are up'
$vpnRows = @($vpn | ForEach-Object { [pscustomobject]@{ Adapter = $_.Name; Description = $_.InterfaceDescription; IP = $ipOf[[int]$_.ifIndex]; MTU = $mtu[[int]$_.ifIndex]; DNS = $dnsOf[[int]$_.ifIndex] } })
if ($vpnRows.Count) { ($vpnRows | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '   None. (If a VPN app says it is connected, its adapter may use a name NetDeck does not recognise - the routes below still tell the truth.)' }
''
'2. Default routes, best first (the lowest metric carries everything not on your local network)'
$routes = @()
foreach ($r in @(Get-NetRoute -AddressFamily IPv4 -DestinationPrefix '0.0.0.0/0' | Sort-Object RouteMetric, InterfaceMetric)) {
  $ad = $adapters | Where-Object { [int]$_.ifIndex -eq [int]$r.InterfaceIndex } | Select-Object -First 1
  if (-not $ad) { continue }
  $routes += [pscustomobject]@{ Adapter = $ad.Name; 'Next hop' = [string]$r.NextHop; Metric = ([int]$r.RouteMetric + [int]$r.InterfaceMetric); VPN = ($vpnIdx -contains [int]$r.InterfaceIndex) }
}
if ($routes.Count) { ($routes | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '   No default route at all.' }
$best = $null; if ($routes.Count) { $best = $routes[0] }
$viaVpn = [bool]($best -and $best.VPN)
$split = 0
if ($vpnIdx.Count) { $split = @(Get-NetRoute -AddressFamily IPv4 | Where-Object { $vpnIdx -contains [int]$_.InterfaceIndex -and $_.DestinationPrefix -ne '0.0.0.0/0' -and $_.DestinationPrefix -notmatch '/32$' -and $_.DestinationPrefix -notlike '224.*' -and $_.DestinationPrefix -notlike '255.*' -and $_.DestinationPrefix -notlike '127.*' }).Count }
$bestMtu = 0; if ($viaVpn) { $bv = $vpn | Where-Object { $_.Name -eq $best.Adapter } | Select-Object -First 1; if ($bv) { $bestMtu = $mtu[[int]$bv.ifIndex] } }
''
'3. Verdict'
if (-not $vpn.Count) { 'No VPN adapter is connected. Traffic leaves through ' + (& { if ($best) { $best.Adapter + ' via ' + $best.'Next hop' } else { 'no route' } }) + '.' }
elseif ($viaVpn) { 'Full tunnel: the default route goes through ' + $best.Adapter + ' (MTU ' + $bestMtu + '). Everything not on your local network travels inside the VPN.' + (& { $under = $routes | Where-Object { -not $_.VPN } | Select-Object -First 1; if ($under) { ' The underlying route via ' + $under.'Next hop' + ' is still there with a higher metric, which is normal.' } else { '' } }) }
else { 'Split tunnel: the VPN is up but the default route still goes through ' + $best.Adapter + ' via ' + $best.'Next hop' + '. Only ' + $split + ' route' + (& { if ($split -ne 1) { 's point' } else { ' points' } }) + ' into the VPN, so most traffic leaves the ordinary way. Corporate VPNs do this on purpose (only work addresses go through the tunnel); a privacy VPN in this state is not protecting you.' }
'SUMMARY ' + ([pscustomobject]@{ vpn = @($vpnRows | ForEach-Object { [pscustomobject]@{ name = $_.Adapter; desc = $_.Description; ip = $_.IP; mtu = $_.MTU; dns = $_.DNS } }); best = (& { if ($best) { [pscustomobject]@{ adapter = $best.Adapter; nexthop = $best.'Next hop'; metric = $best.Metric; vpn = $best.VPN } } else { $null } }); viaVpn = $viaVpn; vpnRoutes = $split; vpnMtu = $bestMtu } | ConvertTo-Json -Compress -Depth 3)

$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
# One STUN "Binding Request" (RFC 5389) to each of two public servers, from the same local port. Each answers with
# the public address:port it saw. Same port from both = endpoint-independent NAT (good); different = symmetric NAT.
function Stun-Query($udp, $server, $port) {
  $ip = $null; try { $ip = ([Net.Dns]::GetHostAddresses($server) | Where-Object { $_.AddressFamily -eq 'InterNetwork' } | Select-Object -First 1) } catch { }
  if (-not $ip) { return $null }
  $req = New-Object byte[] 20
  $req[0] = 0; $req[1] = 1; $req[2] = 0; $req[3] = 0
  $req[4] = 0x21; $req[5] = 0x12; $req[6] = 0xA4; $req[7] = 0x42
  $rnd = New-Object Random; for ($i = 8; $i -lt 20; $i++) { $req[$i] = [byte]$rnd.Next(0, 256) }
  $ep = New-Object Net.IPEndPoint($ip, $port)
  $resp = $null
  for ($try = 0; $try -lt 2 -and -not $resp; $try++) { [void]$udp.Send($req, 20, $ep); $from = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0); try { $resp = $udp.Receive([ref]$from) } catch { $resp = $null } }
  if (-not $resp -or $resp.Length -lt 20) { return $null }
  for ($i = 8; $i -lt 20; $i++) { if ([int]$resp[$i] -ne [int]$req[$i]) { return $null } }
  $len = ([int]$resp[2] -shl 8) + [int]$resp[3]
  $pos = 20
  while (($pos + 4) -le (20 + $len) -and ($pos + 4) -le $resp.Length) {
    $type = ([int]$resp[$pos] -shl 8) + [int]$resp[$pos + 1]; $alen = ([int]$resp[$pos + 2] -shl 8) + [int]$resp[$pos + 3]
    if (($type -eq 32 -or $type -eq 1) -and $alen -ge 8 -and [int]$resp[$pos + 5] -eq 1) {
      $p = ([int]$resp[$pos + 6] -shl 8) + [int]$resp[$pos + 7]
      $oct = @([int]$resp[$pos + 8], [int]$resp[$pos + 9], [int]$resp[$pos + 10], [int]$resp[$pos + 11])
      if ($type -eq 32) { $p = $p -bxor 0x2112; $oct[0] = $oct[0] -bxor 0x21; $oct[1] = $oct[1] -bxor 0x12; $oct[2] = $oct[2] -bxor 0xA4; $oct[3] = $oct[3] -bxor 0x42 }
      return [pscustomobject]@{ server = $server; ip = ($oct -join '.'); port = $p }
    }
    $pos += 4 + $alen + ((4 - ($alen % 4)) % 4)
  }
  return $null
}
$udp = New-Object Net.Sockets.UdpClient; $udp.Client.Bind((New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0))); $udp.Client.ReceiveTimeout = 1500
$localPort = ([Net.IPEndPoint]$udp.Client.LocalEndPoint).Port
$a = Stun-Query $udp 'stun.l.google.com' 19302
$b = Stun-Query $udp 'stun.cloudflare.com' 3478
$udp.Close()
'STUN: "what address and port do you see me as?" - asked from local UDP port ' + $localPort + ' to two different servers'
'   stun.l.google.com:19302    ' + (& { if ($a) { $a.ip + ':' + $a.port } else { 'no answer' } })
'   stun.cloudflare.com:3478   ' + (& { if ($b) { $b.ip + ':' + $b.port } else { 'no answer' } })
''
$nat = 'unknown'; $pub = ''
if ($a -and $b) { $pub = $a.ip; if ($a.ip -eq $b.ip -and $a.port -eq $b.port) { $nat = 'cone' } else { $nat = 'symmetric' } }
elseif ($a -or $b) { $pub = (& { if ($a) { $a.ip } else { $b.ip } }); $nat = 'one-server' }
if ($nat -eq 'cone') { 'NAT type: endpoint-independent ("cone") - both servers saw the same public port' + (& { if ($a.port -eq $localPort) { ', and it matches the local port (no NAT, or a port-preserving one)' } else { '' } }) + '. Calls and games can connect directly. This is the good case.' }
elseif ($nat -eq 'symmetric') { 'NAT type: SYMMETRIC - the router used a different public port for each server. Direct peer-to-peer connections (calls, games, file transfers) often cannot be set up and fall back to a relay, which adds delay, or fail outright. Common behind CGNAT and strict corporate firewalls.' }
elseif ($nat -eq 'one-server') { 'Only one STUN server answered, so the NAT type could not be classified. Public address as seen from outside: ' + $pub }
else { 'No STUN server answered over UDP. Either outbound UDP is blocked on this network (real-time calls will struggle, since they are UDP) or a firewall dropped the replies.' }
'SUMMARY ' + ([pscustomobject]@{ localPort = $localPort; a = $a; b = $b; nat = $nat; publicIp = $pub } | ConvertTo-Json -Compress -Depth 3)

$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$mode = 'snapshot'; $secs = 10
$svc = @{ 53 = 'DNS'; 80 = 'HTTP'; 443 = 'HTTPS'; 22 = 'SSH'; 25 = 'SMTP'; 587 = 'SMTP'; 993 = 'IMAPS'; 123 = 'NTP'; 445 = 'SMB'; 3389 = 'RDP'; 5353 = 'mDNS'; 1900 = 'SSDP'; 8080 = 'HTTP-alt'; 5432 = 'PostgreSQL'; 3306 = 'MySQL'; 6379 = 'Redis'; 1433 = 'MSSQL'; 3478 = 'STUN'; 8443 = 'HTTPS-alt'; 1883 = 'MQTT'; 5900 = 'VNC'; 5060 = 'SIP' }
function Svc($port) { if ($svc.ContainsKey([int]$port)) { return $svc[[int]$port] }; if ([int]$port -eq 0) { return '' }; return [string]$port }
$procs = @{}; foreach ($p in (Get-Process)) { $procs[[int]$p.Id] = $p.ProcessName }
$procs[0] = 'System Idle'; if (-not $procs[4]) { $procs[4] = 'System' }
function Conn-Map {
  # local port -> pid, and per-pid connection facts
  $ports = @{}; $by = @{}
  $tcp = @(Get-NetTCPConnection); $udp = @(Get-NetUDPEndpoint)
  foreach ($c in $tcp) {
    $id = [int]$c.OwningProcess; $ports[[int]$c.LocalPort] = $id
    if (-not $by.ContainsKey($id)) { $by[$id] = @{ Est = 0; Listen = 0; Udp = 0; Remotes = @{} } }
    if ($c.State -eq 'Established') { $by[$id].Est++; $k = $c.RemoteAddress + ':' + (Svc $c.RemotePort); $by[$id].Remotes[$k] = [int]$by[$id].Remotes[$k] + 1 }
    elseif ($c.State -eq 'Listen') { $by[$id].Listen++ }
  }
  foreach ($u in $udp) { $id = [int]$u.OwningProcess; $ports[[int]$u.LocalPort] = $id; if (-not $by.ContainsKey($id)) { $by[$id] = @{ Est = 0; Listen = 0; Udp = 0; Remotes = @{} } }; $by[$id].Udp++ }
  return @{ Ports = $ports; By = $by }
}
function PName($id) { $n = $procs[[int]$id]; if (-not $n) { $n = 'pid ' + $id }; return $n }
if ($mode -eq 'snapshot') {
  $m = Conn-Map
