    $b = $m.By[$id]; if (($b.Est + $b.Listen + $b.Udp) -eq 0) { continue }
    $top = (($b.Remotes.GetEnumerator() | Sort-Object { $_.Value } -Descending | Select-Object -First 3 | ForEach-Object { $_.Key }) -join ', ')
    [pscustomobject]@{ Process = (PName $id); PID = $id; Established = $b.Est; Listening = $b.Listen; UDP = $b.Udp; 'Talking to' = $top }
  }
