$pr = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $pr.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { 'PROCNET-ERROR: measuring traffic per program needs administrator rights. Use "Run as admin" at the top of the window, or pick the default variant, which lists connections without admin.'; exit 1 }
