'Measuring for ' + $secs + ' s which programs send and receive (pktmon, attributed through each program''s ports)...'
Start-Sleep -Seconds $secs
$m1 = Conn-Map
pktmon stop 2>&1 | Out-Null
pktmon etl2txt $etl --out $txt 2>&1 | Out-Null
$ports = @{}; foreach ($k in $m0.Ports.Keys) { $ports[$k] = $m0.Ports[$k] }; foreach ($k in $m1.Ports.Keys) { $ports[$k] = $m1.Ports[$k] }
function Split-Endpoint($s) { if ($s -match '^(\d+\.\d+\.\d+\.\d+)\.(\d+)$') { return @($Matches[1], [int]$Matches[2]) }; if ($s -match '^([0-9A-Fa-f:]+)\.(\d+)$') { return @($Matches[1], [int]$Matches[2]) }; return @($s, 0) }
$acc = @{}; $pk = 0; $unattributed = 0; $other = 0
function Bump($id, $dir, $size, $remote) { if (-not $script:acc.ContainsKey($id)) { $script:acc[$id] = @{ In = 0.0; Out = 0.0; Pk = 0; Rem = @{} } }; $a = $script:acc[$id]; $a.Pk++; if ($dir -eq 'Rx') { $a.In += $size } else { $a.Out += $size }; if ($remote) { $a.Rem[$remote] = [double]$a.Rem[$remote] + $size } }
$rd = New-Object IO.StreamReader($txt); $dir = ''; $size = 0
function Handle($t) {
  $script:pk++
