}
while (($line = $rd.ReadLine()) -ne $null) {
  if ($line -match 'Direction (Rx|Tx).*OriginalSize (\d+)') { $dir = $Matches[1]; $size = [int]$Matches[2]; if ($line -match 'LoggedSize \d+[,\s]+(\S.* > .*)$') { Handle $Matches[1].Trim(); $dir = '' }; continue }
  if (-not $dir) { continue }
  Handle $line.Trim(); $dir = ''
}
$rd.Close()
Remove-Item -LiteralPath $etl, $txt -Force
function Fmt-Bytes($b) { if ($b -ge 1MB) { return ('{0:n1} MB' -f ($b / 1MB)) }; if ($b -ge 1KB) { return ('{0:n0} KB' -f ($b / 1KB)) }; return ([int]$b).ToString() + ' B' }
$total = 0.0; foreach ($a in $acc.Values) { $total += $a.In + $a.Out }
