  $a = $acc[$id]; $name = (& { if ($id -eq -1) { '(unmatched)' } else { PName $id } })
  $top = ($a.Rem.GetEnumerator() | Sort-Object { $_.Value } -Descending | Select-Object -First 1 | ForEach-Object { $_.Key })
  [pscustomobject]@{ Process = $name; PID = (& { if ($id -eq -1) { '' } else { $id } }); Received = (Fmt-Bytes $a.In); Sent = (Fmt-Bytes $a.Out); Packets = $a.Pk; Share = ('{0:p0}' -f (($a.In + $a.Out) / [math]::Max($total, 1))); 'Top remote' = $top; bytes = ($a.In + $a.Out) }
