'Over ' + $secs + ' s this PC moved ' + (Fmt-Bytes $total) + ' in ' + $pk.ToString('n0') + ' packets' + (& { if ($other) { ' (plus ' + $other + ' that were not this PC''s: broadcast, ARP, other devices)' } else { '' } })
''
if ($rows.Count) { ($rows | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '  nothing was sent or received' }
''
$topRow = $rows | Where-Object { $_.PID -ne '' } | Select-Object -First 1
if ($topRow) { 'Busiest program: ' + $topRow.Process + ' (' + $topRow.Share + ' of the traffic, mostly with ' + $topRow.'Top remote' + '). Traffic is matched to a program through the port it was using during the sample; "(unmatched)" is what could not be: connections that opened and closed inside the 10 s, ICMP, and packets that were not this PC''s.' }

