run.command:
$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$svcNames = @{ 53 = 'DNS'; 80 = 'HTTP'; 135 = 'RPC'; 139 = 'NetBIOS'; 443 = 'HTTPS'; 445 = 'SMB'; 3389 = 'RDP'; 5040 = 'Windows CDP'; 5353 = 'mDNS'; 5355 = 'LLMNR'; 1900 = 'SSDP'; 137 = 'NetBIOS'; 138 = 'NetBIOS'; 3702 = 'WS-Disc'; 5432 = 'PostgreSQL'; 3306 = 'MySQL'; 6379 = 'Redis'; 1433 = 'MSSQL'; 22 = 'SSH'; 5900 = 'VNC'; 8080 = 'HTTP-alt'; 7680 = 'Delivery Optimization'; 49664 = 'RPC'; 49665 = 'RPC'; 49666 = 'RPC'; 49667 = 'RPC'; 49668 = 'RPC'; 49669 = 'RPC'; 5985 = 'WinRM'; 5986 = 'WinRM'; 2375 = 'Docker API'; 2376 = 'Docker API' }
$procs = @{}; foreach ($p in (Get-Process)) { $procs[[int]$p.Id] = $p }
$services = @{}; foreach ($s in (Get-CimInstance Win32_Service | Where-Object { $_.ProcessId -gt 0 })) { $services[[int]$s.ProcessId] = @($services[[int]$s.ProcessId]) + $s.Name }
$signers = @{}
function Signer($path) { if (-not $path) { return '' }; if ($script:signers.ContainsKey($path)) { return $script:signers[$path] }; $s = ''; try { $sig = Get-AuthenticodeSignature -LiteralPath $path; if ($sig.Status -eq 'Valid') { $cn = $sig.SignerCertificate.Subject; if ($cn -match 'CN=([^,]+)') { $s = $Matches[1].Trim('"') } else { $s = 'signed' } } elseif ($sig.Status -eq 'NotSigned') { $s = 'UNSIGNED' } else { $s = 'signature ' + $sig.Status } } catch { }; $script:signers[$path] = $s; return $s }
# firewall: which inbound allow rules could admit traffic to a port or program (bulk-joined, see the firewall audit)
$rules = @(Get-NetFirewallRule -Enabled True -Direction Inbound -Action Allow)
# filters come by piping the rules in: the bulk form is denied to standard users and would match everything
$pf = @{}; foreach ($f in ($rules | Get-NetFirewallPortFilter)) { $pf[$f.InstanceID] = $f }
$af = @{}; foreach ($f in ($rules | Get-NetFirewallApplicationFilter)) { $af[$f.InstanceID] = $f }
$sf = @{}; foreach ($f in ($rules | Get-NetFirewallServiceFilter)) { $sf[$f.InstanceID] = $f }
$services2 = @{}; foreach ($k in $services.Keys) { foreach ($n in $services[$k]) { $services2[$n.ToLower()] = $k } }
$active = @(Get-NetConnectionProfile | ForEach-Object { [string]$_.NetworkCategory })
function FwAllows($port, $proto, $path, $ownerPid) {
  $script:curPid = [int]$ownerPid
  foreach ($r in $rules) {
    $prof = [string]$r.Profile; if ($prof -ne 'Any' -and $prof -ne '0' -and -not ($active | Where-Object { $prof -match $_ })) { continue }
    $p = $pf[$r.Name]; $a = $af[$r.Name]
    $protoOk = (-not $p) -or ($p.Protocol -eq 'Any') -or ($p.Protocol -eq $proto)
    $portOk = (-not $p) -or (-not $p.LocalPort) -or ($p.LocalPort -eq 'Any') -or (@($p.LocalPort) -contains [string]$port) -or (@($p.LocalPort) | Where-Object { $_ -match '^(\d+)-(\d+)$' -and [int]$Matches[1] -le $port -and [int]$Matches[2] -ge $port })
    $progOk = (-not $a) -or (-not $a.Program) -or ($a.Program -eq 'Any') -or ($path -and (($a.Program -replace '%SystemRoot%', $env:SystemRoot -replace '%ProgramFiles%', $env:ProgramFiles -replace '%windir%', $env:SystemRoot) -ieq $path))
    if (($a -and $a.Package -and $a.Package -ne 'Any') -or ($r.Name -match '_[a-z0-9]+S-1-')) { $progOk = $false }
    $s = $sf[$r.Name]; $svcOk = $true; if ($s -and $s.Service -and $s.Service -ne 'Any') { $svcOk = ($script:curPid -ne 0 -and $services2.ContainsKey(([string]$s.Service).ToLower()) -and $services2[([string]$s.Service).ToLower()] -eq $script:curPid) }
    if ($protoOk -and $portOk -and $progOk -and $svcOk) { return $r.DisplayName }
  }
  return ''
}
$rows = @()
foreach ($c in (Get-NetTCPConnection -State Listen | Sort-Object LocalPort -Unique)) {
  $id = [int]$c.OwningProcess; $p = $procs[$id]; $path = (& { if ($p) { [string]$p.Path } else { '' } })
  $bound = (& { if ($c.LocalAddress -in '127.0.0.1', '::1') { 'localhost only' } elseif ($c.LocalAddress -in '0.0.0.0', '::') { 'all addresses' } else { $c.LocalAddress } })
  $fw = (& { if ($bound -eq 'localhost only') { '' } else { FwAllows $c.LocalPort 'TCP' $path $id } })
  $rows += [pscustomobject]@{ Port = $c.LocalPort; Proto = 'TCP'; Service = (& { if ($svcNames.ContainsKey([int]$c.LocalPort)) { $svcNames[[int]$c.LocalPort] } else { '' } }); Bound = $bound; Process = (& { if ($p) { $p.ProcessName } elseif ($id -eq 4) { 'System' } else { 'pid ' + $id } }); PID = $id; 'Windows service' = (($services[$id] | Select-Object -First 3) -join ','); Signer = (& { if ($path) { Signer $path } elseif ($id -eq 4) { 'Windows kernel' } else { '(no access)' } }); Started = (& { if ($p -and $p.StartTime) { $p.StartTime.ToString('MMM d HH:mm') } else { '' } }); Firewall = (& { if ($bound -eq 'localhost only') { 'n/a (local)' } elseif ($fw) { 'allowed: ' + $fw } else { 'no allow rule (blocked)' } }); reach = ($bound -ne 'localhost only' -and $fw -ne '') }
}
foreach ($u in (Get-NetUDPEndpoint | Where-Object { $_.LocalPort -lt 49152 } | Sort-Object LocalPort -Unique)) {
  $id = [int]$u.OwningProcess; $p = $procs[$id]; $path = (& { if ($p) { [string]$p.Path } else { '' } })
  $bound = (& { if ($u.LocalAddress -in '127.0.0.1', '::1') { 'localhost only' } elseif ($u.LocalAddress -in '0.0.0.0', '::') { 'all addresses' } else { $u.LocalAddress } })
  $fw = (& { if ($bound -eq 'localhost only') { '' } else { FwAllows $u.LocalPort 'UDP' $path $id } })
  $rows += [pscustomobject]@{ Port = $u.LocalPort; Proto = 'UDP'; Service = (& { if ($svcNames.ContainsKey([int]$u.LocalPort)) { $svcNames[[int]$u.LocalPort] } else { '' } }); Bound = $bound; Process = (& { if ($p) { $p.ProcessName } elseif ($id -eq 4) { 'System' } else { 'pid ' + $id } }); PID = $id; 'Windows service' = (($services[$id] | Select-Object -First 3) -join ','); Signer = (& { if ($path) { Signer $path } elseif ($id -eq 4) { 'Windows kernel' } else { '(no access)' } }); Started = (& { if ($p -and $p.StartTime) { $p.StartTime.ToString('MMM d HH:mm') } else { '' } }); Firewall = (& { if ($bound -eq 'localhost only') { 'n/a (local)' } elseif ($fw) { 'allowed: ' + $fw } else { 'no allow rule (blocked)' } }); reach = ($bound -ne 'localhost only' -and $fw -ne '') }
}
$reach = @($rows | Where-Object { $_.reach }); $unsigned = @($rows | Where-Object { $_.Signer -eq 'UNSIGNED' })
$rows.Count.ToString() + ' listening ports (' + @($rows | Where-Object { $_.Proto -eq 'TCP' }).Count + ' TCP, ' + @($rows | Where-Object { $_.Proto -eq 'UDP' }).Count + ' UDP below 49152): ' + $reach.Count + ' reachable from the network (bound to all addresses AND allowed by the firewall on the current profile), ' + @($rows | Where-Object { $_.Bound -eq 'localhost only' }).Count + ' localhost only.'
''
($rows | Sort-Object { -not $_.reach }, Proto, Port | Select-Object Port, Proto, Service, Bound, Process, PID, 'Windows service', Signer, Started, Firewall | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd()
