function Split-Endpoint($s) { if ($s -match '^(\d+\.\d+\.\d+\.\d+)\.(\d+)$') { return @($Matches[1], [int]$Matches[2]) }; if ($s -match '^([0-9A-Fa-f:]+)\.(\d+)$') { return @($Matches[1], [int]$Matches[2]) }; return @($s, 0) }
$rows = New-Object Collections.Generic.List[object]; $n = 0; $shown = 0; $dir = ''; $size = 0; $time = ''
function Add-Row($t) {
  $script:n++
  $proto = ''; $src = ''; $dst = ''; $info = ''
  if ($t -match 'ethertype ARP[^:]*:\s*(.*)$') { $proto = 'ARP'; $info = $Matches[1]; if ($info -match 'who-has ([^,\s]+) tell ([^,\s]+)') { $src = $Matches[2]; $dst = $Matches[1] } elseif ($info -match '(\S+) is-at') { $src = $Matches[1] } }
  else {
    $body = $t; if ($t -match 'length \d+: (.*)$') { $body = $Matches[1] }
    if ($body -match '^(\S+) > (\S+?):? (.*)$') {
      $sp = Split-Endpoint $Matches[1]; $dp = Split-Endpoint $Matches[2]; $rest = $Matches[3]
      $src = $sp[0] + (& { if ($sp[1]) { ':' + $sp[1] } else { '' } }); $dst = $dp[0] + (& { if ($dp[1]) { ':' + $dp[1] } else { '' } })
      $l4 = 'other'; if ($rest -like 'Flags *') { $l4 = 'TCP' } elseif ($rest -match '^UDP|UDP, length|^\d+[+*]? |\d+/\d+/\d+') { $l4 = 'UDP' } elseif ($rest -match 'ICMP6|ICMPv6') { $l4 = 'ICMPv6' } elseif ($rest -match 'ICMP') { $l4 = 'ICMP' }
      $port = 0; if ($svc.ContainsKey($dp[1])) { $port = $dp[1] } elseif ($svc.ContainsKey($sp[1])) { $port = $sp[1] }
      $proto = $l4; if ($port) { $proto = $svc[$port]; if ($l4 -eq 'UDP' -and $port -eq 443) { $proto = 'QUIC' } }
      $info = $rest
