      $port = 0; if ($svc.ContainsKey($dp[1])) { $port = $dp[1] } elseif ($svc.ContainsKey($sp[1])) { $port = $sp[1] }
      $proto = $l4; if ($port) { $proto = $svc[$port]; if ($l4 -eq 'UDP' -and $port -eq 443) { $proto = 'QUIC' } }
      $info = $rest
    } else { $proto = '?'; $info = $t }
  }
  if ($only -eq 'dns' -and $proto -ne 'DNS') { return }
  if ($only -eq 'syn' -and -not ($proto -ne 'ARP' -and $info -match '^Flags \[S\]')) { return }
  if ($script:shown -ge $max) { return }
  $script:shown++
  $info = $info -replace '\s+', ' '; if ($info.Length -gt 90) { $info = $info.Substring(0, 87) + '...' }
  $rows.Add([pscustomobject]@{ '#' = $script:n; Time = $time; Dir = $dir; Source = $src; Destination = $dst; Proto = $proto; Bytes = $size; Info = $info })
}
$rd = New-Object IO.StreamReader($last)
while (($line = $rd.ReadLine()) -ne $null) {
  if ($line -match 'Direction (Rx|Tx).*OriginalSize (\d+)') {
    $dir = (& { if ($Matches[1] -eq 'Rx') { 'in' } else { 'out' } }); $size = [int]$Matches[2]
    $time = ''; if ($line -match '::\S+ (\d\d:\d\d:\d\d\.\d\d\d)') { $time = $Matches[1] } elseif ($line -match '::(\d\d:\d\d:\d\d\.\d\d\d)') { $time = $Matches[1] }
    if ($line -match 'LoggedSize \d+[,\s]+(\S.* > .*)$') { Add-Row $Matches[1].Trim(); $dir = '' }
    continue
  }
  if (-not $dir) { continue }
  Add-Row $line.Trim(); $dir = ''
}
$rd.Close()
$what = (& { if ($only -eq 'dns') { 'DNS packets' } elseif ($only -eq 'syn') { 'connection attempts (TCP SYN)' } else { 'packets' } })
$age = ''; if ($m) { $mins = [int]((Get-Date) - [datetime]$m.when).TotalMinutes; $age = (& { if ($mins -lt 1) { 'just now' } elseif ($mins -lt 60) { $mins.ToString() + ' min ago' } elseif ($mins -lt 2880) { [math]::Round($mins / 60).ToString() + ' h ago' } else { [math]::Round($mins / 1440).ToString() + ' days ago' } }) }
'Last capture' + (& { if ($m) { ': ' + ([datetime]$m.when).ToString('ddd d MMM yyyy HH:mm:ss') + ' (' + $age + '), ' + $m.secs + ' s on ' + $m.adapters + ', filter: ' + $m.filter } else { '' } }) + ' - ' + $n.ToString('n0') + ' packets decoded, showing ' + $shown.ToString('n0') + ' ' + $what + (& { if ($shown -lt $n -and $only -eq 'all') { ' (the first ' + $max.ToString('n0') + '; use the larger variant for more)' } else { '' } })
''
if ($rows.Count) { ($rows | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '  no ' + $what + ' in this capture' }
''
'Dir is from this PC''s point of view (in = received). Info is pktmon''s tcpdump-style decode: TCP flags [S] = connection attempt, [S.] = accepted, [F]/[R] = closing; "A? name" = DNS question, "n/0/0 A ip" = DNS answer. Press "Table" to sort and filter.'

run.command:
$ErrorActionPreference = 'SilentlyContinue'
$secs = 10
$pr = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $pr.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { 'HUNT-ERROR: counting dropped packets needs administrator rights. Use "Run as admin" at the top of the window, then run this playbook again.'; exit 1 }
pktmon stop 2>&1 | Out-Null; pktmon filter remove 2>&1 | Out-Null
$started = pktmon start --capture --counters-only 2>&1
if ($LASTEXITCODE -ne 0) { 'HUNT-ERROR: pktmon could not start. ' + (($started | Out-String).Trim()); exit 1 }
function Get-CountersJson { return (pktmon counters --json 2>&1 | Out-String) }
function Walk-Metrics($node, $prefix, $bag) {
  if ($node -is [pscustomobject]) {
    $props = $node.PSObject.Properties
    $tags = @(); foreach ($p in $props) { if ($p.Value -is [string] -and $p.Name -notmatch 'Reason|Name|Description') { $tags += $p.Value } }
    $pre = $prefix; if ($tags.Count) { $pre = (($prefix, ($tags -join '/')) | Where-Object { $_ }) -join '/' }
    foreach ($p in $props) {
      $v = $p.Value
      if ($v -is [string] -and $p.Name -match 'Reason' -and $v) { $bag.Reason = $v; continue }
      if ($p.Name -eq 'Id') { continue }
      if ($v -is [int] -or $v -is [long] -or $v -is [double] -or $v -is [decimal]) { $k = (($pre, $p.Name) | Where-Object { $_ }) -join '/'; $bag.M[$k] = [double]$bag.M[$k] + [double]$v; continue }
      if ($null -eq $v -or $v -is [string] -or $v -is [bool]) { continue }
      if ($v -is [pscustomobject] -and $v.PSObject.Properties['Id'] -and $v.PSObject.Properties['Name']) { continue }
      $sub = $pre; if ($p.Name -notmatch '^(Counters?|Children|Components?)$') { $sub = (($pre, $p.Name) | Where-Object { $_ }) -join '/' }
      Walk-Metrics $v $sub $bag
    }
  } elseif ($node -is [System.Collections.IEnumerable] -and $node -isnot [string]) {
    foreach ($item in $node) { if ($item -is [pscustomobject] -and $item.PSObject.Properties['Id'] -and $item.PSObject.Properties['Name']) { continue }; Walk-Metrics $item $prefix $bag }
  }
}
function Find-Components($node, $list) {
  if ($node -is [pscustomobject]) {
    if ($node.PSObject.Properties['Id'] -and $node.PSObject.Properties['Name']) { $list.Add($node) }
    foreach ($p in $node.PSObject.Properties) { if ($p.Value -isnot [string]) { Find-Components $p.Value $list } }
  } elseif ($node -is [System.Collections.IEnumerable] -and $node -isnot [string]) { foreach ($i in $node) { Find-Components $i $list } }
}
function Snap {
  $raw = [string](Get-CountersJson); $script:lastRaw = $raw; $script:lastErr = ''
  $body = $raw; $i = $raw.IndexOfAny([char[]]@('{', '[')); if ($i -gt 0) { $body = $raw.Substring($i) }
  $obj = $null; try { $obj = $body | ConvertFrom-Json } catch { $script:lastErr = $_.Exception.Message }
  if (-not $obj) { if ($script:lastErr) { return $null }; return @{} }
  $comps = New-Object Collections.Generic.List[object]; Find-Components $obj $comps
  $snap = @{}
  foreach ($c in $comps) {
    $bag = @{ M = @{}; Reason = '' }; Walk-Metrics $c '' $bag
    $type = ''; foreach ($p in $c.PSObject.Properties) { if ($p.Name -match 'Type|Kind|Category' -and $p.Value -is [string]) { $type = $p.Value; break } }
    $snap[[string]$c.Id] = @{ Name = [string]$c.Name; Type = $type; M = $bag.M; Reason = $bag.Reason }
  }
  return $snap
}
function Sum-Keys($m, $pattern, $exclude) { $s = 0.0; foreach ($k in $m.Keys) { if ($k -match $pattern -and ($exclude -eq '' -or $k -notmatch $exclude)) { $s += $m[$k] } }; return $s }
function Classify($m) {
  $in = Sum-Keys $m '(Rx|In|Ingress).*Packet|Packet.*(Rx|In|Ingress)' 'Drop|Byte'
  $out = Sum-Keys $m '(Tx|Out|Egress).*Packet|Packet.*(Tx|Out|Egress)' 'Drop|Byte'
  $drop = Sum-Keys $m 'Drop' 'Byte'
  if ($in -eq 0 -and $out -eq 0 -and $drop -eq 0) { $in = Sum-Keys $m 'Packet' 'Drop|Byte' }
  return @{ In = $in; Out = $out; Drop = $drop }
}
function Delta($a, $b) { $d = @{}; foreach ($id in $b.Keys) { $m = @{}; foreach ($k in $b[$id].M.Keys) { $prev = 0.0; if ($a -and $a.ContainsKey($id) -and $a[$id].M.ContainsKey($k)) { $prev = $a[$id].M[$k] }; $m[$k] = $b[$id].M[$k] - $prev }; $d[$id] = @{ Name = $b[$id].Name; Type = $b[$id].Type; M = $m; Reason = $b[$id].Reason } }; return $d }
# the router, from the same rule the context strip uses
$gw = ''; foreach ($r in @(Get-NetRoute -AddressFamily IPv4 -DestinationPrefix '0.0.0.0/0' | Sort-Object RouteMetric, InterfaceMetric)) { $a = @(Get-NetIPAddress -InterfaceIndex $r.InterfaceIndex -AddressFamily IPv4 | Where-Object { $_.IPAddress -notlike '169.254.*' -and $_.AddressState -eq 'Preferred' }); if ($a.Count) { $gw = $r.NextHop; break } }
$first = $null; for ($w = 0; $w -lt 6; $w++) { $first = Snap; if ($null -eq $first) { break }; if ($first.Count -gt 0) { break }; Start-Sleep -Seconds 1 }
if ($null -ne $first -and $first.Count -eq 0) { pktmon stop 2>&1 | Out-Null; 'HUNT-ERROR: pktmon counted no packets on any adapter in 6 s. Is the network connected? Try again while something is using it.'; exit 1 }
if ($null -eq $first) { pktmon stop 2>&1 | Out-Null; 'HUNT-ERROR: pktmon returned no counters (its --json output could not be read).'; if ($script:lastErr) { 'Reader said: ' + $script:lastErr }; exit 1 }
$nicIds = @($first.Keys | Where-Object { $first[$_].Type -match 'NIC|Adapter|Miniport' }); if (-not $nicIds.Count) { $nicIds = @($first.Keys) }
# traffic to count: a 5 MB download in the background, plus one ping a second to the router and to the internet
Add-Type -AssemblyName System.Net.Http
$hc = New-Object System.Net.Http.HttpClient; $hc.Timeout = [TimeSpan]::FromSeconds(40)
$dlUrl = 'https://speed.cloudflare.com/__down?bytes=5000000'; $dlStart = [Diagnostics.Stopwatch]::StartNew(); $dl = $hc.GetByteArrayAsync($dlUrl)
'Counting packets on ' + $first.Count + ' components for ' + $secs + ' s while pinging ' + (& { if ($gw) { 'the router (' + $gw + ')' } else { '(no router found)' } }) + ' and the internet (1.1.1.1), and downloading 5 MB from speed.cloudflare.com.'
''
$gwSent = 0; $gwLost = 0; $inetSent = 0; $inetLost = 0; $gwMs = @(); $inetMs = @()
$prev = $first
for ($i = 1; $i -le $secs; $i++) {
  $pg = $null; if ($gw) { $pg = (New-Object System.Net.NetworkInformation.Ping).SendPingAsync($gw, 900); $gwSent++ }
  $pi = (New-Object System.Net.NetworkInformation.Ping).SendPingAsync('1.1.1.1', 900); $inetSent++
  Start-Sleep -Seconds 1
  $cur = Snap; $d = $null; if ($cur) { $d = Delta $prev $cur; $prev = $cur }
  $parts = @(); if ($d) { $parts = foreach ($id in ($nicIds | Sort-Object { $first[$_].Name })) { if ($d.ContainsKey($id)) { $c = Classify $d[$id].M; if ($c.In + $c.Out + $c.Drop -gt 0) { $d[$id].Name + ': in ' + [int]$c.In + '  out ' + [int]$c.Out + (& { if ($c.Drop -gt 0) { '  DROPS ' + [int]$c.Drop } else { '' } }) } } } }
  $pgTxt = ''; if ($pg) { if ($pg.Status -eq 'RanToCompletion' -and $pg.Result.Status -eq 'Success') { $gwMs += $pg.Result.RoundtripTime; $pgTxt = 'router ' + $pg.Result.RoundtripTime + ' ms' } else { $gwLost++; $pgTxt = 'router LOST' } }
  $piTxt = ''; if ($pi.Status -eq 'RanToCompletion' -and $pi.Result.Status -eq 'Success') { $inetMs += $pi.Result.RoundtripTime; $piTxt = 'internet ' + $pi.Result.RoundtripTime + ' ms' } else { $inetLost++; $piTxt = 'internet LOST' }
  ('{0,3} s  ' -f $i) + (& { if ($parts) { $parts -join '   |   ' } else { '(quiet)' } }) + '     ping: ' + ((@($pgTxt, $piTxt) | Where-Object { $_ }) -join ', ')
}
$last = $prev
pktmon stop 2>&1 | Out-Null
try { [void]$dl.Wait(4000) } catch { }
$dlBytes = 0; $dlSecs = [math]::Round($dlStart.Elapsed.TotalSeconds, 1); $dlOk = $false
if ($dl.Status -eq 'RanToCompletion') { $dlBytes = $dl.Result.Length; $dlOk = $true }
$total = Delta $first $last
''
'Totals over ' + $secs + ' s, every layer (drops first)'
$rows = @(foreach ($id in $total.Keys) { $c = Classify $total[$id].M; if ($c.In + $c.Out + $c.Drop -gt 0) { [pscustomobject]@{ Component = $total[$id].Name; Type = $total[$id].Type; In = [int]$c.In; Out = [int]$c.Out; Drops = [int]$c.Drop; 'Last drop reason' = (& { if ($c.Drop -gt 0) { $total[$id].Reason } else { '' } }) } } })
if ($rows.Count) { ($rows | Sort-Object Drops, In -Descending | Format-Table -AutoSize | Out-String -Width 4096).TrimEnd() } else { '  no packets moved on any component' }
''
$dropsTotal = 0; $top = $null; foreach ($r in ($rows | Sort-Object Drops -Descending)) { $dropsTotal += $r.Drops; if (-not $top -and $r.Drops -gt 0) { $top = $r } }
$avg = { param($a) if ($a.Count) { [math]::Round(($a | Measure-Object -Average).Average) } else { 0 } }
'Ping: router ' + (& { if ($gw) { ($gwSent - $gwLost).ToString() + '/' + $gwSent + ' answered' + (& { if ($gwMs.Count) { ', avg ' + (& $avg $gwMs) + ' ms' } else { '' } }) } else { 'not tested' } }) + ' - internet ' + ($inetSent - $inetLost) + '/' + $inetSent + ' answered' + (& { if ($inetMs.Count) { ', avg ' + (& $avg $inetMs) + ' ms' } else { '' } })
'Download: ' + (& { if ($dlOk) { [math]::Round($dlBytes / 1000000, 1).ToString() + ' MB in ' + $dlSecs + ' s (' + [math]::Round($dlBytes * 8 / 1000000 / [math]::Max($dlSecs, 0.1), 1) + ' Mbit/s)' } else { 'did not finish within ' + $dlSecs + ' s' } })
'Drops: ' + (& { if ($dropsTotal -eq 0) { 'none on any layer' } else { $dropsTotal.ToString() + ', most on "' + $top.Component + '" (' + $top.Type + ')' + (& { if ($top.'Last drop reason') { ', reason ' + $top.'Last drop reason' } else { '' } }) } })
''
'SUMMARY ' + ([pscustomobject]@{ gw = $gw; gwSent = $gwSent; gwLost = $gwLost; gwAvg = (& $avg $gwMs); inetSent = $inetSent; inetLost = $inetLost; inetAvg = (& $avg $inetMs); dlOk = $dlOk; dlBytes = $dlBytes; dlSecs = $dlSecs; drops = $dropsTotal; dropLayer = (& { if ($top) { $top.Component } else { '' } }); dropType = (& { if ($top) { $top.Type } else { '' } }); dropReason = (& { if ($top) { [string]$top.'Last drop reason' } else { '' } }); layers = $rows.Count } | ConvertTo-Json -Compress)
